/* V5: Operational tasks and configurable workflow rules */
function tasksPage(){
 if(state.user.role==='student')return go('dashboard');
 shell(`<div class="subheading"><div><div class="eyebrow">SERVICE CONSOLE / MY WORK</div><h1>Assigned Review Tasks</h1><p class="muted">Claim, prioritize and complete review tasks. Completed cases automatically close associated tasks.</p></div><button class="button secondary" id="refresh-tasks">Refresh</button></div>
 <section class="grid">${stat('Open tasks',state.tasks.length)}${stat('High priority',state.tasks.filter(t=>t.priority==='high').length)}${stat('Overdue',state.tasks.filter(t=>t.due_at<new Date().toISOString()).length)}${stat('Unassigned',state.tasks.filter(t=>!t.assigned_to).length)}</section>
 <section class="card panel"><h2>Work Queue</h2><div class="tablewrap"><table><thead><tr><th>Priority</th><th>Case / Student</th><th>Due</th><th>Assigned to</th><th>Actions</th></tr></thead><tbody>${state.tasks.map(t=>`<tr><td>${badge(t.priority)}</td><td><strong>${h(t.certification_title)}</strong><p class="muted">${h(t.student_name)}</p></td><td>${h(t.due_at.slice(0,10))}</td><td>${h(t.assignee_name||'Unassigned')}</td><td><div class="action-row"><button class="button small secondary" data-task="${h(t.id)}" data-op="claim">Claim</button><button class="button small secondary" data-task="${h(t.id)}" data-op="complete">Complete</button><button class="button small" data-case="${h(t.certification_id)}">Open record</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No open tasks.</td></tr>'}</tbody></table></div></section>`);
 document.getElementById('refresh-tasks').onclick=()=>go('tasks');
 document.querySelectorAll('[data-task]').forEach(b=>b.onclick=async()=>{try{await api('/api/workflow/tasks/'+encodeURIComponent(b.dataset.task),'PATCH',{action:b.dataset.op});notice('Task updated');await go('tasks')}catch(e){notice(e.message,true)}});
 document.querySelectorAll('[data-case]').forEach(b=>b.onclick=async()=>{try{state.certs=(await api('/api/certifications')).items;detail(b.dataset.case)}catch(e){notice(e.message,true)}});
}
function workflowStudio(){if(state.user.role!=='admin')return go('dashboard');
 shell(`<div class="subheading"><div><div class="eyebrow">AUTOMATION / ADMINISTRATION</div><h1>Workflow Studio</h1><p class="muted">Configured rules trigger in-app tasks and notices when certifications are submitted.</p></div></div>
 <div class="note">Rules use predefined events and actions. No arbitrary scripts, third-party emails, or paid automations.</div>
 <section class="card panel"><h2>Active Workflow Rules</h2><div class="tablewrap"><table><thead><tr><th>Event</th><th>Action</th><th>Priority</th><th>Due (days)</th><th>Status</th></tr></thead><tbody>${state.rules.map(r=>`<tr><td>${h(r.event)}</td><td>${h(r.action)}</td><td>${h(r.priority)}</td><td>${h(r.days_due)}</td><td><button class="button small secondary" data-rule="${h(r.id)}" data-enabled="${h(r.enabled)}">${r.enabled?'Disable':'Enable'}</button></td></tr>`).join('')}</tbody></table></div></section>
 <section class="card panel"><h2>Create Automation</h2><form id="rule-add"><div class="formgrid">${fieldSelect('When','event',['submitted','needs_revision'])}${fieldSelect('Then','action',['task','notify'])}${fieldSelect('Priority','priority',['normal','high','low'])}${input('Due in days (1–30)','days_due','number','3','min="1" max="30" required')}</div><div class="form-actions"><button class="button">Create Rule</button></div></form></section>`);
 document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=async()=>{try{await api('/api/workflow/rules/'+encodeURIComponent(b.dataset.rule),'PATCH',{enabled:b.dataset.enabled!=='1'});await go('workflow')}catch(e){notice(e.message,true)}});
 document.getElementById('rule-add').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.currentTarget));d.days_due=Number(d.days_due);await api('/api/workflow/rules','POST',d);notice('Workflow rule created');await go('workflow')}catch(e){notice(e.message,true)}};
}
