/* V6 — Global search and record workspaces. All data comes from role-scoped API endpoints. */
function globalSearch(){
 shell(`<div class="subheading"><div><div class="eyebrow">COMMAND CENTER</div><h1>Global Search</h1><p class="muted">Search certification records, catalog entries, programs and authorized student profiles.</p></div></div><section class="card panel"><label for="global-query">Search across the workspace</label><div class="toolbar"><input id="global-query" type="search" autocomplete="off" placeholder="Search by certification, issuer, program or student…" aria-label="Global search"/><button class="button" id="run-global">Search</button></div><div id="global-results" aria-live="polite" class="search-results"><div class="empty">Enter at least two characters to search.</div></div></section>`);
 const input=document.getElementById('global-query'),out=document.getElementById('global-results');
 async function run(){const q=input.value.trim();if(q.length<2){out.innerHTML='<div class="empty">Enter at least two characters.</div>';return;}out.textContent='Searching…';try{const d=await api('/api/search?q='+encodeURIComponent(q));state.results=d;out.innerHTML=[['Certifications',d.certifications,x=>`${h(x.title)} — ${h(x.issuer)} <small>(${h(x.status)})</small>`],['Students',d.students,x=>h(x.full_name)],['Catalog',d.catalog,x=>h(x.title)],['Programs',d.programs,x=>h(x.title)]].map(([label,items,fmt])=>`<div class="search-section"><h3>${label} <small>${items.length}</small></h3>${items.length?items.map(x=>`<button class="search-row" data-kind="${label}" data-id="${h(x.id)}">${fmt(x)} <span aria-hidden="true">›</span></button>`).join(''):'<p class="muted">No matches</p>'}</div>`).join('');out.querySelectorAll('[data-kind]').forEach(b=>b.onclick=async()=>{const kind=b.dataset.kind,id=b.dataset.id;if(kind==='Students')return loadStudent360(id);if(kind==='Certifications'){state.certs=(await api('/api/certifications')).items;return detail(id);}if(kind==='Catalog')return go('catalog');return go('programs');});}catch(e){out.textContent='Search failed: '+e.message;}}
 document.getElementById('run-global').onclick=run;input.addEventListener('keydown',e=>{if(e.key==='Enter')run()});input.focus();
}
function studentDirectory(){if(state.user.role==='student')return go('dashboard');const items=state.users.filter(x=>x.role==='student'||!x.role);shell(`<div class="subheading"><div><div class="eyebrow">PEOPLE / STUDENTS</div><h1>Student 360 Directory</h1><p class="muted">Complete student workspaces; view individual certification, program, and goal activity.</p></div></div><div class="card panel"><div class="toolbar"><input id="student-filter" type="search" placeholder="Filter students" aria-label="Filter students"/></div><div id="student-list"></div></div>`);
 const el=document.getElementById('student-list');function show(term=''){el.innerHTML=`<div class="tablewrap"><table><thead><tr><th>Student</th><th>Account</th><th>Action</th></tr></thead><tbody>${items.filter(x=>(x.full_name+' '+x.email).toLowerCase().includes(term.toLowerCase())).map(x=>`<tr><td><strong>${h(x.full_name)}</strong><div class="muted">${h(x.email)}</div></td><td>${x.active?'Active':'Inactive'}</td><td><button class="button secondary small" data-profile="${h(x.id)}">Open 360 Profile</button></td></tr>`).join('')||'<tr><td colspan="3">No students found.</td></tr>'}</tbody></table></div>`;el.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>loadStudent360(b.dataset.profile));}show();document.getElementById('student-filter').oninput=e=>show(e.target.value);
}
async function loadStudent360(id){try{state.profile=await api('/api/students/'+encodeURIComponent(id)+'/360');state.view='student360';render()}catch(e){notice(e.message,true)}}
function student360(){
 if(!state.profile)return go('students');
 const d=state.profile,s=d.student,p=s.profile||{},approved=d.certifications.filter(c=>c.status==='approved').length,isAdmin=state.user.role==='admin';
 const formField=(label,key,type='text',extra='')=>`<div class="field"><label for="p-${key}">${h(label)}</label><input id="p-${key}" name="${key}" type="${type}" value="${h(key in p?p[key]:s[key])}" ${extra}></div>`;
 shell(`<div class="subheading"><div><div class="eyebrow">STUDENT 360 / STUDENT RECORD</div><h1>${h(s.full_name)}</h1><p class="muted">${h(s.email)} · ${s.active?'Active':'Inactive'} account · Joined ${h(s.created_at)}</p></div><button id="back-students" class="button secondary">← Student directory</button></div>
 <section class="grid">${stat('Credentials',d.certifications.length)}${stat('Approved',approved)}${stat('Goals',d.goals.length)}${stat('Programs',d.programs.length)}</section>
 <div class="student-record-tabs" role="navigation" aria-label="Student record sections"><a href="#account-profile">Account & Profile</a><a href="#student-credentials">Certifications</a><a href="#student-pathways">Pathways & Goals</a><a href="#student-activity">History</a></div>
 <section id="account-profile" class="card panel"><div class="subheading"><div><h2>Account & Student Profile</h2><p class="muted">${isAdmin?'Administrators can update account details and manage access.':'View-only student profile for authorized staff.'}</p></div>${isAdmin?'<span class="record-tag">Administrator editing</span>':'<span class="record-tag">Read-only</span>'}</div>
 ${isAdmin?`<form id="student-profile-form"><div class="formgrid">${formField('Full name','full_name','text','required minlength="2" maxlength="100"')}${formField('Email address','email','email','required maxlength="200"')}${formField('Department / division','department','text','maxlength="100"')}${formField('Cohort or enrollment term','cohort','text','maxlength="60"')}${formField('Advisor / contact','advisor','text','maxlength="100"')}${formField('Internal demo reference','internal_reference','text','maxlength="60"')}</div><div class="field"><label for="p-staff_notes">Staff notes (demo only)</label><textarea id="p-staff_notes" name="staff_notes" rows="4" maxlength="1200">${h(p.staff_notes)}</textarea></div><label class="profile-toggle"><input type="checkbox" name="active" ${s.active?'checked':''}> Account active</label><p class="muted">Deactivating a student revokes their current sessions. Changing their email changes their login address. Do not enter real protected student information in this demo.</p><button type="submit" class="button">Save student profile</button></form><hr class="subtle-rule"><h3>Account recovery</h3><p class="muted">Issue a temporary password and revoke all sessions. The student must change it when they next sign in.</p><form id="student-reset-form" class="reset-inline"><div class="field"><label for="student-temporary-password">New temporary password</label><input id="student-temporary-password" name="temporary_password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></div><button type="button" class="button secondary" id="generate-student-password">Generate</button><button type="submit" class="button secondary">Reset password</button></form>`:
 `<dl class="profile-readonly">${[['Full name',s.full_name],['Email',s.email],['Department',p.department],['Cohort',p.cohort],['Advisor',p.advisor],['Internal reference',p.internal_reference],['Staff notes',p.staff_notes],['Account status',s.active?'Active':'Inactive']].map(([k,v])=>`<div><dt>${h(k)}</dt><dd>${h(v||'—')}</dd></div>`).join('')}</dl>`}</section>
 <div class="split-panels"><section id="student-credentials" class="card panel"><h2>Certifications</h2>${d.certifications.map(x=>`<div class="metric-line"><span>${h(x.title)} <small class="muted">${h(x.issuer)} · ${h(date(x.earned_on))}</small></span>${badge(x.status)}</div>`).join('')||'<p class="muted">No certifications recorded.</p>'}</section>
 <section id="student-pathways" class="card panel"><h2>Program memberships</h2>${d.programs.map(x=>`<div class="metric-line"><span>${h(x.title)}</span><small>${h(x.joined_at)}</small></div>`).join('')||'<p class="muted">No program membership.</p>'}<h2 style="margin-top:20px">Development goals</h2>${d.goals.map(x=>`<div class="metric-line"><span>${h(x.title)}</span><strong>${h(x.status)}</strong></div>`).join('')||'<p class="muted">No goals recorded.</p>'}</section></div>
 <section id="student-activity" class="card panel"><h2>Recent activity</h2>${d.activity.map(x=>`<div class="metric-line"><span>${h(x.event.replaceAll('_',' '))}</span><small>${h(x.occurred_at)}</small></div>`).join('')||'<p class="muted">No activity recorded.</p>'}</section>`);
 document.getElementById('back-students').onclick=()=>go('students');
 if(!isAdmin)return;
 document.getElementById('student-profile-form').onsubmit=async e=>{
  e.preventDefault();const f=new FormData(e.currentTarget);const data=Object.fromEntries(f.entries());data.active=f.has('active');
  if(!data.active&&s.active&&!confirm('Deactivate this student? All their active sessions will be revoked.'))return;
  if(data.email.trim().toLowerCase()!==s.email.toLowerCase()&&!confirm('Change the student login email address?'))return;
  try{await api('/api/students/'+encodeURIComponent(s.id)+'/profile','PATCH',data);notice('Student account and profile saved');await loadStudent360(s.id)}catch(err){notice(err.message,true)}
 };
 document.getElementById('generate-student-password').onclick=()=>{
  const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';
  const bytes=new Uint8Array(22);crypto.getRandomValues(bytes);
  const temp=Array.from(bytes,x=>chars[x%chars.length]).join('')+'A1';
  const el=document.getElementById('student-temporary-password');el.type='text';el.value=temp;el.focus();notice('Generated a temporary password. Share it privately; do not commit it to GitHub.');
 };
 document.getElementById('student-reset-form').onsubmit=async e=>{
  e.preventDefault();if(!confirm('Reset this student password and revoke all their active sessions?'))return;
  const data=Object.fromEntries(new FormData(e.currentTarget));
  try{await api('/api/students/'+encodeURIComponent(s.id)+'/reset-password','POST',data);e.currentTarget.reset();notice('Temporary password set. Give it to the student using a secure channel.')}catch(err){notice(err.message,true)}
 };
}
function reportStudio(){
 if(state.user.role==='student')return go('dashboard');
 const r=state.studio||{rows:[],trend:[],metrics:{},group:'status',issuers:[]};
 const groups=[['status','Certification status'],['issuer','Issuing organization'],['month','Submission month'],['program','Academic program'],['student','Student (staff only)']];
 shell(`<div class="subheading"><div><div class="eyebrow">ANALYTICS / REPORT BUILDER</div><h1>Reporting Studio</h1><p class="muted">Filter credential data, compare activity trends, inspect groups, and export an aggregated CSV report.</p></div></div>
 <section class="card panel"><h2>Report criteria</h2><div class="report-filter-grid">
 <div class="field"><label for="report-group">Group by</label><select id="report-group">${groups.map(([v,l])=>`<option value="${h(v)}">${h(l)}</option>`).join('')}</select></div>
 <div class="field"><label for="report-status">Status</label><select id="report-status"><option value="">All statuses</option>${['pending','approved','rejected','needs_revision'].map(v=>`<option value="${v}">${h(v.replace('_',' '))}</option>`).join('')}</select></div>
 <div class="field"><label for="report-issuer">Issuer contains</label><input id="report-issuer" type="search" maxlength="100" placeholder="e.g. CompTIA" value="${h(r.issuer||'')}"></div>
 <div class="field"><label for="report-program">Program contains</label><input id="report-program" type="search" maxlength="100" placeholder="Any program" value="${h(r.program||'')}"></div>
 <div class="field"><label for="report-from">Submitted on/after</label><input id="report-from" type="date" value="${h(r.from||'')}"></div>
 <div class="field"><label for="report-to">Submitted on/before</label><input id="report-to" type="date" value="${h(r.to||'')}"></div></div>
 <div class="toolbar"><button class="button" id="run-report">Run report</button><button class="button secondary" id="clear-report">Clear filters</button><button class="button secondary" id="export-report">Export CSV</button></div></section>
 <section id="studio-results" aria-live="polite"></section>`);
 const group=document.getElementById('report-group'),status=document.getElementById('report-status'),issuer=document.getElementById('report-issuer'),program=document.getElementById('report-program'),from=document.getElementById('report-from'),to=document.getElementById('report-to'),out=document.getElementById('studio-results');
 group.value=r.group||'status';status.value=r.status==='all'?'':r.status||'';
 function display(){const d=state.studio||{rows:[],trend:[],metrics:{}};const m=d.metrics||{};const max=Math.max(1,...(d.rows||[]).map(x=>x.total));out.innerHTML=`<div class="grid report-metrics">${stat('Matching certifications',m.total||0)}${stat('Approved',m.approved||0)}${stat('Pending',m.pending||0)}${stat('Students represented',m.students||0)}</div><section class="card panel"><h2>Results by ${h((groups.find(x=>x[0]===d.group)||[])[1]||'group')}</h2><p class="muted">${h(d.disclaimer||'')} · ${(d.rows||[]).length} groups</p><div class="report-bars">${(d.rows||[]).map(x=>`<div class="report-line"><span title="${h(x.label||'Not specified')}">${h(x.label||'Not specified')}</span><div class="report-meter"><div style="width:${Math.round(x.total/max*100)}%"></div></div><strong>${h(x.total)}</strong></div>`).join('')||'<div class="empty">No matching records.</div>'}</div></section><section class="card panel"><h2>Monthly submission trend</h2>${(d.trend||[]).map(x=>`<div class="metric-line"><span>${h(x.month)}</span><strong>${h(x.total)} submissions</strong></div>`).join('')||'<p class="muted">No activity in the selected date range.</p>'}</section>`;}
 display();
 document.getElementById('run-report').onclick=async()=>{try{if(from.value&&to.value&&from.value>to.value)throw Error('The beginning date must be before the ending date');const params=new URLSearchParams({group:group.value,status:status.value,issuer:issuer.value,program:program.value,from:from.value,to:to.value});state.studio=await api('/api/reports/studio?'+params.toString());display();notice('Report refreshed')}catch(e){notice(e.message,true)}};
 document.getElementById('clear-report').onclick=async()=>{try{state.studio=await api('/api/reports/studio?group=status');reportStudio()}catch(e){notice(e.message,true)}};
 document.getElementById('export-report').onclick=()=>{const d=state.studio||{rows:[]},q=v=>{const x=String(v??'');return '"'+(/^[=+\-@\t\r]/.test(x)?"'"+x:x).replaceAll('"','""')+'"'};const meta=[['Report group',d.group],['Status filter',d.status],['Issuer filter',d.issuer],['Program filter',d.program],['Start date',d.from],['End date',d.to],['Total records',d.metrics?.total],['Approved',d.metrics?.approved],['Pending',d.metrics?.pending],['Students represented',d.metrics?.students]];const csv=[...meta.map(([k,v])=>q(k)+','+q(v)), '', 'Group,Count',...(d.rows||[]).map(x=>q(x.label)+','+q(x.total)), '', 'Month,Submissions',...(d.trend||[]).map(x=>q(x.month)+','+q(x.total))].join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pgcc-report-studio.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);};
}
function securityCenterPage(){if(state.user.role!=='admin')return go('dashboard');const d=state.securityCenter||{accounts:[],events:[],active_sessions:0,high_attempt_keys:0};shell(`<div class="subheading"><div><div class="eyebrow">ADMINISTRATION / SECURITY</div><h1>Security & QA Center</h1><p class="muted">Account inventory, live session totals, login risk indicators and important audit events.</p></div><button id="reload-security" class="button secondary">Refresh</button></div><section class="grid">${stat('Active sessions',d.active_sessions)}${stat('Elevated attempt keys',d.high_attempt_keys)}${stat('Accounts',d.accounts.reduce((n,x)=>n+x.total,0))}${stat('Security events',d.events.length)}</section><div class="split-panels"><section class="card panel"><h2>Account inventory</h2>${d.accounts.map(x=>`<div class="metric-line"><span>${h(x.role)} · ${x.active?'Active':'Inactive'}</span><strong>${h(x.total)}</strong></div>`).join('')}</section><section class="card panel"><h2>Security events</h2>${d.events.map(x=>`<div class="metric-line"><span>${h(x.event.replaceAll('_',' '))}<small class="muted"> ${h(x.actor||'System')}</small></span><small>${h(x.occurred_at)}</small></div>`).join('')||'<p class="muted">No events</p>'}</section></div><p class="note">${h(d.disclaimer)}</p>`);document.getElementById('reload-security').onclick=()=>go('security-center');}

refresh();
